-- =============================================================================
-- 16. commerce_payment_notify_domain
-- =============================================================================
-- Admin-configured notify domains for the order payment/refund webhook URLs.
-- Multiple domains per tenant scope are allowed; exactly one active domain is
-- the default. Resolution: exact organization row -> organization '0'
-- (platform) row -> ORDER_PAYMENT_WEBHOOK_BASE_URL env.
CREATE TABLE IF NOT EXISTS commerce_payment_notify_domain (
    id                TEXT PRIMARY KEY,
    tenant_id         TEXT NOT NULL,
    organization_id   TEXT NOT NULL DEFAULT '0',
    protocol          TEXT NOT NULL DEFAULT 'https'
                      CHECK (protocol IN ('https', 'http')),
    hostname          TEXT NOT NULL,
    port              INTEGER,
    is_default        BOOLEAN NOT NULL DEFAULT FALSE,
    status            TEXT NOT NULL DEFAULT 'active'
                      CHECK (status IN ('active', 'inactive')),
    sort_order        INTEGER NOT NULL DEFAULT 0,
    version           BIGINT NOT NULL DEFAULT 0,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    deleted_at        TIMESTAMPTZ NULL,
    CHECK (port IS NULL OR (port >= 1 AND port <= 65535))
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_commerce_payment_notify_domain_identity
    ON commerce_payment_notify_domain (tenant_id, COALESCE(organization_id, '0'), protocol, hostname)
    WHERE deleted_at IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS ux_commerce_payment_notify_domain_default
    ON commerce_payment_notify_domain (tenant_id, COALESCE(organization_id, '0'))
    WHERE is_default AND deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_commerce_payment_notify_domain_scope
    ON commerce_payment_notify_domain (tenant_id, organization_id, status, sort_order, id)
    WHERE deleted_at IS NULL;


-- =============================================================================
-- 17. commerce_payment_domain_setting
-- =============================================================================
-- Admin-configured payment domain settings (支付中心 → 支付设置 → 域名设置).
-- One row per tenant scope (exact organization row, or the platform '0' row)
-- stores the H5 payment domain: the origin used to build the order cashier
-- URL / QR code payload and the default H5 return URL handed to redirect-style
-- PSP products. Resolution: exact organization row -> organization '0'
-- (platform) row -> deployment SDKWORK_COMMERCE_CASHIER_BASE_URL / platform
-- default. The callback (notify) domain remains commerce_payment_notify_domain.
CREATE TABLE IF NOT EXISTS commerce_payment_domain_setting (
    id                TEXT PRIMARY KEY,
    tenant_id         TEXT NOT NULL,
    organization_id   TEXT NOT NULL DEFAULT '0',
    h5_protocol       TEXT NOT NULL DEFAULT 'https'
                      CHECK (h5_protocol IN ('https', 'http')),
    h5_hostname       TEXT NOT NULL,
    h5_port           INTEGER,
    h5_status         TEXT NOT NULL DEFAULT 'active'
                      CHECK (h5_status IN ('active', 'inactive')),
    version           BIGINT NOT NULL DEFAULT 1,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    deleted_at        TIMESTAMPTZ NULL,
    CHECK (h5_port IS NULL OR (h5_port >= 1 AND h5_port <= 65535))
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_commerce_payment_domain_setting_scope
    ON commerce_payment_domain_setting (tenant_id, organization_id)
    WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_commerce_payment_domain_setting_lookup
    ON commerce_payment_domain_setting (tenant_id, organization_id, h5_status, id)
    WHERE deleted_at IS NULL;


-- =============================================================================
-- 18. commerce_payment_cashier_token_setting
-- =============================================================================
-- Admin-configured anonymous-cashier key epoch (支付中心 → 支付设置 → 收银台密钥).
-- One row per tenant; a missing row means epoch 1 (the legacy derivation) and a
-- missing tenant row falls back to the platform '0' row. Only the public epoch
-- counter and rotation metadata live here — the root signing secret stays a
-- deployment secret, so a database dump cannot mint cashier tokens. Rotating
-- increments `key_epoch`; new tokens carry the epoch and new mints derive the
-- tenant key from it, while tokens issued under the previous epoch keep verifying
-- until their 15-minute expiry.
CREATE TABLE IF NOT EXISTS commerce_payment_cashier_token_setting (
    tenant_id   TEXT PRIMARY KEY,
    key_epoch   BIGINT NOT NULL DEFAULT 1 CHECK (key_epoch >= 1),
    rotated_at  TIMESTAMPTZ NULL,
    rotated_by  TEXT NOT NULL DEFAULT '',
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);


-- =============================================================================
-- 19. commerce_payment_cashier_link
-- =============================================================================
-- Server-side short-id mapping for anonymous cashier links. The QR/URL carries
-- only a 128-bit short id (`/cashier/s1.<22 chars>`); the real signed capability
-- token is stored encrypted here and resolved by the order/IAM services. The
-- existing `/cashier/{segment}` URL shape is unchanged. One active link per
-- (tenant, order) keeps QR re-issues idempotent; the real token is AES-256-GCM
-- encrypted with a key derived from the deployment secret + tenant + epoch, so a
-- database dump cannot mint or redeem cashier tokens.
CREATE TABLE IF NOT EXISTS commerce_payment_cashier_link (
    short_id          TEXT PRIMARY KEY,
    tenant_id         TEXT NOT NULL,
    order_id          TEXT NOT NULL,
    token_id          TEXT NOT NULL,
    key_epoch         BIGINT NOT NULL CHECK (key_epoch >= 1),
    token_ciphertext  TEXT NOT NULL,
    status            TEXT NOT NULL DEFAULT 'active'
                      CHECK (status IN ('active', 'revoked', 'expired')),
    expires_at        TIMESTAMPTZ NOT NULL,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_commerce_payment_cashier_link_active_order
    ON commerce_payment_cashier_link (tenant_id, order_id)
    WHERE status = 'active';

CREATE INDEX IF NOT EXISTS idx_commerce_payment_cashier_link_expiry
    ON commerce_payment_cashier_link (expires_at);

