-- purpose: Enforce business-number uniqueness at the database boundary and
--   support provider-transaction lookups. `refund_no` is the webhook
--   resolution key (per-tenant) and `payment_intent_no` is the operator-facing
--   intent number; both previously had no unique constraint, so a collision
--   made refund webhook resolution nondeterministic. The partial index on
--   `provider_transaction_id` serves PSP native-id lookups without a seq scan.
--   The indexes are IF NOT EXISTS idempotent so they also apply on top of the
--   updated baseline on fresh installs.
-- reversible: true
-- rollback: drop the three indexes
-- transactional: true
-- lock: lightweight
-- lock_timeout: 2s
-- statement_timeout: 30s
-- note: creation fails loudly if legacy data already contains duplicate
--   numbers; dedup is a data fix that must precede this migration.

BEGIN;

CREATE UNIQUE INDEX IF NOT EXISTS ux_commerce_refund_tenant_refund_no
    ON commerce_refund (tenant_id, refund_no)
    WHERE deleted_at IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS ux_commerce_payment_intent_tenant_intent_no
    ON commerce_payment_intent (tenant_id, payment_intent_no)
    WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS ix_commerce_payment_attempt_provider_transaction
    ON commerce_payment_attempt (tenant_id, provider_code, provider_transaction_id)
    WHERE provider_transaction_id IS NOT NULL AND deleted_at IS NULL;

COMMIT;

-- folded migration: migrations/postgres/0003_payment_attempt_provider_code.up.sql
-- sdkwork:migration
-- id: 0003_payment_attempt_provider_code
-- engine: postgres
-- module: sdkwork-payment
-- purpose: Backfill the `provider_code` column on `commerce_payment_attempt`
--   for long-lived databases created before the column existed in the
--   baseline. The reconciliation/compensation claim query selects
--   `provider_code` from this table, so a database created from an older
--   baseline fails every compensation pass with "column provider_code does
--   not exist". The column is nullable on backfill: existing rows describe
--   attempts whose provider channel is no longer recoverable, and new rows
--   insert it explicitly (the baseline enforces NOT NULL on fresh installs).
--   The IF NOT EXISTS form is idempotent so it also applies on top of the
--   updated baseline on fresh installs.
-- reversible: true
-- rollback: down-migration
-- transactional: true
-- lock: lightweight
-- lock_timeout: 2s
-- statement_timeout: 30s
ALTER TABLE commerce_payment_attempt
    ADD COLUMN IF NOT EXISTS provider_code TEXT;

-- folded migration: migrations/postgres/0004_payment_domain_setting.up.sql
-- sdkwork:migration
-- id: 0004_payment_domain_setting
-- engine: postgres
-- module: sdkwork-payment
-- purpose: Add `commerce_payment_domain_setting`, the typed settings store for
--   the admin payment center's domain configuration (支付设置 → 域名设置).
--   It holds the H5 payment domain used to build the order cashier URL / QR
--   code payload and the default H5 return URL for redirect-style PSP products.
--   The callback (notify) domain keeps its own multi-row table
--   `commerce_payment_notify_domain`. IF NOT EXISTS keeps the migration
--   idempotent on databases already created from the updated baseline.
-- reversible: true
-- rollback: down-migration
-- transactional: true
-- lock: lightweight
-- lock_timeout: 2s
-- statement_timeout: 30s

BEGIN;

CREATE TABLE IF NOT EXISTS commerce_payment_domain_setting (
    id                TEXT PRIMARY KEY,
    tenant_id         TEXT NOT NULL,
    organization_id   TEXT NOT NULL DEFAULT '0',
    h5_protocol       TEXT NOT NULL DEFAULT 'https'
                      CHECK (h5_protocol IN ('https', 'http')),
    h5_hostname       TEXT NOT NULL,
    h5_port           INTEGER,
    h5_status         TEXT NOT NULL DEFAULT 'active'
                      CHECK (h5_status IN ('active', 'inactive')),
    version           BIGINT NOT NULL DEFAULT 1,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    deleted_at        TIMESTAMPTZ NULL,
    CHECK (h5_port IS NULL OR (h5_port >= 1 AND h5_port <= 65535))
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_commerce_payment_domain_setting_scope
    ON commerce_payment_domain_setting (tenant_id, organization_id)
    WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_commerce_payment_domain_setting_lookup
    ON commerce_payment_domain_setting (tenant_id, organization_id, h5_status, id)
    WHERE deleted_at IS NULL;

COMMIT;

-- folded migration: migrations/postgres/0005_payment_cashier_token_setting.up.sql
-- sdkwork:migration
-- id: 0005_payment_cashier_token_setting
-- engine: postgres
-- module: sdkwork-payment
-- purpose: Add `commerce_payment_cashier_token_setting`, the per-tenant key epoch
--   for anonymous-cashier capability-token rotation (支付中心 → 支付设置 →
--   收银台密钥). Only the public epoch counter and rotation metadata are stored;
--   the root signing secret stays a deployment secret, so neither a database
--   dump nor a read-only database account can mint cashier tokens.
--   Resolution: tenant row -> platform '0' row -> epoch 1 (legacy derivation).
-- reversible: true
-- rollback: down-migration
-- transactional: true
-- lock: lightweight
-- lock_timeout: 2s
-- statement_timeout: 30s

BEGIN;

CREATE TABLE IF NOT EXISTS commerce_payment_cashier_token_setting (
    tenant_id   TEXT PRIMARY KEY,
    key_epoch   BIGINT NOT NULL DEFAULT 1 CHECK (key_epoch >= 1),
    rotated_at  TIMESTAMPTZ NULL,
    rotated_by  TEXT NOT NULL DEFAULT '',
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

COMMIT;

-- folded migration: migrations/postgres/0006_payment_cashier_token_secret.up.sql
-- sdkwork:migration
-- id: 0006_payment_cashier_token_secret
-- engine: postgres
-- module: sdkwork-payment
-- purpose: Store the anonymous-cashier signing secret in the payment database so
--   the payment center (支付中心 → 支付设置 → 收银台密钥) can generate and rotate
--   it. The secret is sealed with the deployment key-encryption key
--   (`SDKWORK_COMMERCE_CASHIER_TOKEN_SECRET`) before it is written, so a database
--   dump without the deployment KEK cannot mint cashier tokens. A short-lived
--   previous secret keeps in-flight links valid across a rotation.
-- reversible: true
-- rollback: down-migration
-- transactional: true
-- lock: lightweight
-- lock_timeout: 2s
-- statement_timeout: 30s

BEGIN;

ALTER TABLE commerce_payment_cashier_token_setting
    ADD COLUMN IF NOT EXISTS secret_ciphertext TEXT NOT NULL DEFAULT '',
    ADD COLUMN IF NOT EXISTS secret_encryption_key_id TEXT NOT NULL DEFAULT '',
    ADD COLUMN IF NOT EXISTS secret_encryption_algorithm TEXT NOT NULL DEFAULT '',
    ADD COLUMN IF NOT EXISTS secret_fingerprint_sha256 TEXT NOT NULL DEFAULT '',
    ADD COLUMN IF NOT EXISTS secret_updated_at TIMESTAMPTZ NULL,
    ADD COLUMN IF NOT EXISTS previous_secret_ciphertext TEXT NOT NULL DEFAULT '',
    ADD COLUMN IF NOT EXISTS previous_secret_encryption_key_id TEXT NOT NULL DEFAULT '',
    ADD COLUMN IF NOT EXISTS previous_secret_encryption_algorithm TEXT NOT NULL DEFAULT '',
    ADD COLUMN IF NOT EXISTS previous_secret_expires_at TIMESTAMPTZ NULL;

COMMIT;

-- folded migration: migrations/postgres/0007_payment_cashier_token_enabled.up.sql
-- sdkwork:migration
-- id: 0007_payment_cashier_token_enabled
-- engine: postgres
-- module: sdkwork-payment
-- purpose: Add the per-tenant anonymous-cashier enable switch. Disabling stops
--   new capability-token minting immediately; already-issued tokens remain valid
--   only until their own expiry because verification reads the same setting.
-- reversible: true
-- rollback: down-migration
-- transactional: true
-- lock: lightweight
-- lock_timeout: 2s
-- statement_timeout: 30s

BEGIN;

ALTER TABLE commerce_payment_cashier_token_setting
    ADD COLUMN IF NOT EXISTS enabled BOOLEAN NOT NULL DEFAULT TRUE;

COMMIT;

-- folded migration: migrations/postgres/0008_payment_cashier_link.up.sql
-- sdkwork:migration
-- id: 0008_payment_cashier_link
-- engine: postgres
-- module: sdkwork-payment
-- purpose: Add `commerce_payment_cashier_link`, the server-side short-id mapping
--   for anonymous cashier links. The QR/URL carries only a 128-bit short id; the
--   real signed capability token is stored encrypted here and resolved by the
--   order/IAM services. This keeps the existing `/cashier/{segment}` URL shape
--   while cutting the QR payload from ~460 to ~64 characters.
--   One active link per (tenant, order) keeps QR re-issues idempotent.
-- reversible: true
-- rollback: down-migration
-- transactional: true
-- lock: lightweight
-- lock_timeout: 2s
-- statement_timeout: 30s

BEGIN;

CREATE TABLE IF NOT EXISTS commerce_payment_cashier_link (
    short_id          TEXT PRIMARY KEY,
    tenant_id         TEXT NOT NULL,
    order_id          TEXT NOT NULL,
    token_id          TEXT NOT NULL,
    key_epoch         BIGINT NOT NULL CHECK (key_epoch >= 1),
    token_ciphertext  TEXT NOT NULL,
    status            TEXT NOT NULL DEFAULT 'active'
                      CHECK (status IN ('active', 'revoked', 'expired')),
    expires_at        TIMESTAMPTZ NOT NULL,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_commerce_payment_cashier_link_active_order
    ON commerce_payment_cashier_link (tenant_id, order_id)
    WHERE status = 'active';

CREATE INDEX IF NOT EXISTS idx_commerce_payment_cashier_link_expiry
    ON commerce_payment_cashier_link (expires_at);

COMMIT;

-- =============================================================================
-- Payment admin audit trail
-- =============================================================================
-- Append-only record of privileged configuration changes (credential create,
-- rotate, revoke, account changes). It records who changed what in which request
-- and never the secret material, so it can be retained and queried without
-- becoming a second secret store (INTEGRATION_SPEC audit requirements).
CREATE TABLE IF NOT EXISTS commerce_payment_admin_audit_log (
    id                TEXT PRIMARY KEY,
    tenant_id         TEXT NOT NULL,
    organization_id   TEXT NOT NULL DEFAULT '0',
    actor_user_id     TEXT NOT NULL,
    action            TEXT NOT NULL,
    resource_type     TEXT NOT NULL,
    resource_id       TEXT NOT NULL,
    request_no        TEXT,
    detail            JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_commerce_payment_admin_audit_tenant_time
    ON commerce_payment_admin_audit_log (tenant_id, created_at DESC, id DESC);

CREATE INDEX IF NOT EXISTS idx_commerce_payment_admin_audit_resource
    ON commerce_payment_admin_audit_log (tenant_id, resource_type, resource_id, created_at DESC);

-- =============================================================================
-- Checkout scene policy (configurable product resolution)
-- =============================================================================
-- Which provider product serves a buyer context is deployment/tenant
-- configuration: an iOS app paying with WeChat needs `wechat_app`, a browser needs
-- `wechat_h5`, a mini-program `wechat_jsapi`. Keeping that mapping in the database
-- lets an operator support a new platform without a release. Resolution order:
-- scene+architecture+os > scene+architecture > scene (see
-- `checkout_scene_policy.rs`); `any` (or NULL) is the wildcard value.
CREATE TABLE IF NOT EXISTS commerce_payment_checkout_scene_policy (
    id                 TEXT PRIMARY KEY,
    tenant_id          TEXT NOT NULL,
    organization_id    TEXT NOT NULL DEFAULT '0',
    scene              TEXT NOT NULL,
    app_architecture   TEXT NOT NULL DEFAULT 'any',
    os_family          TEXT NOT NULL DEFAULT 'any',
    payment_method     TEXT NOT NULL,
    product_code       TEXT NOT NULL,
    status             TEXT NOT NULL DEFAULT 'active'
                       CHECK (status IN ('active', 'inactive')),
    priority           INTEGER NOT NULL DEFAULT 100,
    metadata           JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    deleted_at         TIMESTAMPTZ NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS ux_commerce_payment_checkout_scene_policy
    ON commerce_payment_checkout_scene_policy
       (tenant_id, organization_id, LOWER(scene), LOWER(app_architecture), LOWER(os_family), LOWER(payment_method))
    WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_commerce_payment_checkout_scene_policy_lookup
    ON commerce_payment_checkout_scene_policy
       (tenant_id, organization_id, payment_method, status)
    WHERE deleted_at IS NULL;
